                    const m = neighbors[Math.floor(rng.next()*neighbors.length)];
                    const nr = curr.r+dr[m], nc = curr.c+dc[m];
                    passage[curr.r][curr.c][dn[m]] = true; passage[nr][nc][opp[dn[m]]] = true;
                    v[nr][nc] = true; s_stack.push({r:nr, c:nc});
                } else s_stack.pop();
            }
                for(let r=0; r<ROWS; r++) for(let c=0; c<COLS; c++) {
                    mazeWalls[r][c].n = !passage[r][c].n; mazeWalls[r][c].e = !passage[r][c].e;
                    mazeWalls[r][c].s = !passage[r][c].s; mazeWalls[r][c].w = !passage[r][c].w;
                }
            const bRng = new LCG(s);
            for(let i=0; i<24; i++) {
                let p = [0,1,2,3]; for(let j=3; j>0; j--) { let k = Math.floor(bRng.next()*(j+1)); [p[j], p[k]]=[p[k], p[j]]; }
                bots.push(new Bot(i, 0, 0, exitPos.r, exitPos.c, p));
            }
            window.game.bots = bots;
        }
