            if (w.s) { ctx.beginPath(); ctx.moveTo(c*CELL_SIZE, (r+1)*CELL_SIZE); ctx.lineTo((c+1)*CELL_SIZE, (r+1)*CELL_SIZE); ctx.stroke(); }
            if (w.w) { ctx.beginPath(); ctx.moveTo(c*CELL_SIZE, r*CELL_SIZE); ctx.lineTo(c*CELL_SIZE, (r+1)*CELL_SIZE); ctx.stroke(); }
